using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Reflection;
using System.Collections.Generic;
using System.Windows.Forms;
using CircuitoStudio;
internal static class MotorStartingTests {
 static int n;static void Check(bool ok,string label){n++;if(!ok)throw new Exception(label);}static void Near(double a,double b,string label){Check(Math.Abs(a-b)<1e-8*Math.Max(1,Math.Abs(b)),label);}
 static void Reject(Action a,string label){bool rejected=false;try{a();}catch(InvalidDataException){rejected=true;}Check(rejected,label);}
 static T Field<T>(object o,string name){return (T)o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
 static Project Fixture(){var p=new Project();p.Source.Model=SourceModel.ImpedanciaDefinida;p.Source.LineVoltage=400;p.Source.DefinedPhaseROhm=.01;p.Source.DefinedPhaseXOhm=.02;p.Source.NetworkReference="Alimentação sintética de ensaio";var b=new Board{Id="Q",Voltage=400};var c=new Circuit{Id="M",Voltage=400,Phases=PhaseMode.Trifasico,PhaseLabel="ABC",PowerKw=1,PowerFactor=.8,DemandFactor=.5,LengthM=100,CableMm2=10,Notes="Nota preservada"};c.Cable.ResistanceOhmKm=1;c.Cable.ReactanceOhmKm=.1;c.Cable.Reference="Cabo sintético de ensaio";b.Circuits.Add(c);p.Boards.Add(b);return p;}
 static void Evidence(Project project,Circuit circuit,string name){string directory=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"referencias-motor");Directory.CreateDirectory(directory);project.Save(Path.Combine(directory,name+".circuito"));var value=Engineering.Analyze(project).For(circuit).MotorStarting;var culture=System.Globalization.CultureInfo.InvariantCulture;File.WriteAllText(Path.Combine(directory,name+".csv"),"CircuitId;NominalA;StartingDropPercent\n"+circuit.Id+";"+value.NominalCurrentA.ToString("R",culture)+";"+value.StartingDropPercent.Value.ToString("R",culture)+"\n");}
 static MotorStartingData Data(){return new MotorStartingData{ShaftKw=7.5,Efficiency=.9,StartingCurrentA=90,StartingPowerFactor=.3,StartingSeconds=2,AllowedStartDropPercent=3,Source="Motor sintético; revisão de ensaio 1"};}
 [STAThread] public static int Main(){string dir=Path.Combine(Path.GetTempPath(),"motor-starting-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{
  var p=Fixture();var b=p.Boards[0];var c=b.Circuits[0];var data=Data();MotorStarting.Apply(p,b,c,data,PhaseMode.Trifasico,400,.8);p.Validate();Near(c.PowerKw,8.333333333333334,"shaft converted to electrical input");Check(c.Kind=="Motor"&&c.Notes=="Nota preservada","apply retains notes and identifies motor");data.StartingCurrentA=180;Check(c.MotorStarting.StartingCurrentA==90,"applied snapshot independent of later input edits");
  var study=Engineering.Analyze(p);var result=study.For(c).MotorStarting;Near(result.NominalCurrentA,8333.333333333334/(Math.Sqrt(3)*400*.8),"nominal current excludes demand factor");Near(study.For(c).CurrentA,result.NominalCurrentA*.5,"running demand current remains distinct");Near(result.PathROhm.Value,.11,"path includes source R and cable R");Near(result.PathXOhm.Value,.03,"path includes source X and cable X");double expected=100*Math.Sqrt(3)*90*(.11*.3+.03*Math.Sqrt(.91))/400;Near(result.StartingDropPercent.Value,expected,"independent full-path constant-current analytical starting drop");Check(result.Status=="OK","only declared variation criterion passes with complete data");Evidence(p,c,"terminal");
  c.DemandFactor=1;Near(Engineering.Analyze(p).For(c).MotorStarting.StartingDropPercent.Value,expected,"starting current not reduced by demand factor");c.DemandFactor=.25;Near(Engineering.Analyze(p).For(c).MotorStarting.StartingDropPercent.Value,expected,"replacement removes running motor contribution exactly");
  c.MotorStarting.AllowedStartDropPercent=2;Check(Engineering.Analyze(p).For(c).MotorStarting.Status=="Falha","declared start limit exceeded");c.MotorStarting.AllowedStartDropPercent=expected;Check(Engineering.Analyze(p).For(c).MotorStarting.Status=="OK","start variation exact limit accepted");c.MotorStarting.AllowedStartDropPercent=null;Check(Engineering.Analyze(p).For(c).MotorStarting.Status=="Pendente","start limit not inherited from steady-state limit");c.MotorStarting.AllowedStartDropPercent=3;
  var other=new Circuit{Id="OTHER",Voltage=400,Phases=PhaseMode.Trifasico,PhaseLabel="ABC",PowerKw=6,PowerFactor=1,CableMm2=10};other.Cable.Reference="Cabo de ensaio";b.Circuits.Add(other);double otherSourceDrop=100*.01*6000/(400*400);Near(Engineering.Analyze(p).For(c).MotorStarting.StartingDropPercent.Value,expected+otherSourceDrop,"other balanced load preserved at common source");b.Circuits.Remove(other);
  c.MotorStarting.StartingPowerFactor=null;Check(!Engineering.Analyze(p).For(c).MotorStarting.StartingDropPercent.HasValue,"missing starting PF not assumed unity");c.MotorStarting.StartingPowerFactor=.3;c.MotorStarting.StartingSeconds=0;Check(Engineering.Analyze(p).For(c).MotorStarting.Status=="Pendente","unknown starting duration remains pending");c.MotorStarting.StartingSeconds=2;c.MotorStarting.StartingCurrentA=0;Check(!Engineering.Analyze(p).For(c).MotorStarting.StartingDropPercent.HasValue,"unknown starting current remains pending");c.MotorStarting.StartingCurrentA=90;
  c.MotorStarting.Source="";Check(Engineering.Analyze(p).For(c).MotorStarting.Status=="Pendente","unreferenced motor data not accepted");c.MotorStarting.Source="Motor sintético rev. 1";c.Cable.Reference="";Check(Engineering.Analyze(p).For(c).MotorStarting.Status=="Pendente","unreferenced cable data not accepted");c.Cable.Reference="Cabo sintético";
  p.Source.DefinedPhaseXOhm=null;Check(!Engineering.Analyze(p).For(c).MotorStarting.StartingDropPercent.HasValue,"incomplete source impedance stays pending");p.Source.DefinedPhaseXOhm=.02;
  p.Source.Model=SourceModel.UPS;p.Source.UPSMode=UPSOperatingMode.Inversor;p.Source.UPSCurrentLimitKA=.18;p.Source.UPSCurrentLimitSeconds=.2;Check(!Engineering.Analyze(p).For(c).MotorStarting.StartingDropPercent.HasValue,"UPS inverter not modeled as voltage source for starting drop");p.Source.Model=SourceModel.GeradorSincrono;p.Source.GeneratorRatedKva=1000;p.Source.GeneratorXdPercent=20;Check(!Engineering.Analyze(p).For(c).MotorStarting.StartingDropPercent.HasValue,"generator starting dynamics not approximated by static subtransient impedance");p.Source.Model=SourceModel.ImpedanciaDefinida;
  c.MotorStarting.StartingPowerFactor=0;Near(Engineering.Analyze(p).For(c).MotorStarting.StartingDropPercent.Value,100*Math.Sqrt(3)*90*.03/400,"explicit zero start PF distinct from unknown");c.MotorStarting.StartingPowerFactor=.3;
  var radial=Fixture();var rb=radial.Boards[0];var rm=rb.Circuits[0];var child=new Board{Id="CHILD",Voltage=400};rb.Circuits.Remove(rm);child.Circuits.Add(rm);radial.Boards.Add(child);var feeder=new Circuit{Id="FEED",ChildBoardId="CHILD",Voltage=400,Phases=PhaseMode.Trifasico,PhaseLabel="ABC",PowerKw=999,DemandFactor=.2,LengthM=50,CableMm2=25};feeder.Cable.ResistanceOhmKm=.5;feeder.Cable.ReactanceOhmKm=.04;feeder.Cable.Reference="Alimentador sintético";rb.Circuits.Add(feeder);MotorStarting.Apply(radial,child,rm,Data(),PhaseMode.Trifasico,400,.8);var radialResult=Engineering.Analyze(radial).For(rm).MotorStarting;Near(radialResult.PathROhm.Value,.135,"starting path includes feeder and terminal resistance");Near(radialResult.PathXOhm.Value,.032,"starting path includes feeder and terminal reactance");Near(radialResult.StartingDropPercent.Value,100*Math.Sqrt(3)*90*(.135*.3+.032*Math.Sqrt(.91))/400,"radial starting analytical case with replacement through feeder");Evidence(radial,rm,"radial");feeder.Cable.ResistanceOhmKm=0;feeder.CableMm2=0;Check(!Engineering.Analyze(radial).For(rm).MotorStarting.StartingDropPercent.HasValue,"unknown upstream cable prevents total starting result");feeder.Cable.ResistanceOhmKm=.5;feeder.CableMm2=25;MotorStarting.Apply(radial,child,rm,Data(),PhaseMode.Monofasico,230.94,.8);Check(Engineering.Analyze(radial).For(rm).MotorStarting.Status=="Pendente","single phase nominal motor allowed but startup model stays pending");
  double before=c.PowerKw;var snapshot=c.MotorStarting;data=Data();data.Efficiency=0;Reject(delegate{MotorStarting.Apply(p,b,c,data,PhaseMode.Trifasico,400,.8);},"invalid efficiency rejected");Check(c.PowerKw==before&&Object.ReferenceEquals(snapshot,c.MotorStarting),"invalid application preserves current motor atomically");data=Data();Reject(delegate{MotorStarting.Apply(p,b,c,data,PhaseMode.Trifasico,220,.8);},"wrong line voltage rejected");Reject(delegate{MotorStarting.Apply(p,new Board(),c,data,PhaseMode.Trifasico,400,.8);},"unrelated board rejected");
  foreach(double invalid in new[]{double.NaN,-1.0,double.PositiveInfinity}){data=Data();data.StartingCurrentA=invalid;Reject(data.Validate,"invalid starting current rejected");}data=Data();data.StartingPowerFactor=1.01;Reject(data.Validate,"invalid start PF rejected");data=Data();data.ShaftKw=1e9;data.Efficiency=.001;Reject(data.Validate,"excessive derived electrical power rejected");
  c.PowerKw=7;Reject(p.Validate,"manual input cannot silently contradict shaft/efficiency snapshot");c.PowerKw=before;
  string path=Path.Combine(dir,"motor.circuito");p.Save(path);string saved=File.ReadAllText(path);Check(saved.Contains("\"FileVersion\":4")&&saved.Contains("motor-start-v1"),"motor uses format 4 with capability guard");var restored=Project.Load(path);var rc=restored.Boards[0].Circuits[0];Check(rc.MotorStarting.StartingCurrentA==90&&rc.MotorStarting.Source==c.MotorStarting.Source,"motor data and reference survive reopen");Near(Engineering.Analyze(restored).For(rc).MotorStarting.StartingDropPercent.Value,expected,"reopened starting calculation reproducible");
  File.WriteAllText(path,saved.Replace("motor-start-v1","future-machine-v1"));Reject(delegate{Project.Load(path);},"unknown capability rejected rather than silently dropped");File.WriteAllText(path,saved.Replace("[\"motor-start-v1\"]","[]"));Reject(delegate{Project.Load(path);},"missing required capability rejected");File.WriteAllText(path,saved.Replace("\"FileVersion\":4","\"FileVersion\":3"));Reject(delegate{Project.Load(path);},"legacy format cannot carry motor model");File.WriteAllText(path,saved);
  string report=EngineeringReport.Memory(p,Engineering.Analyze(p));Check(report.Contains("RENDIMENTO E PARTIDA DO MOTOR — M")&&report.Contains("Motor sintético rev. 1")&&report.Contains("não é multiplicada pelo fator de demanda"),"report preserves source and startup method");Check(report.Contains("não calcula aceleração")||report.Contains("Não calcula aceleração"),"limitations remain explicit");
  string previousExe=Environment.GetEnvironmentVariable("CIRCUITO_QA_PREVIOUS_EXE");if(!String.IsNullOrWhiteSpace(previousExe)){var assembly=Assembly.LoadFile(Path.GetFullPath(previousExe));var loader=assembly.GetType("CircuitoStudio.Project").GetMethod("Load",BindingFlags.Public|BindingFlags.Static);bool rejected=false;try{loader.Invoke(null,new object[]{path});}catch(TargetInvocationException ex){rejected=ex.InnerException is InvalidDataException;}Check(rejected,"previous released executable rejects new motor format rather than losing metadata");}
  MotorStarting.Remove(rc);restored.Save(path);Check(File.ReadAllText(path).Contains("\"FileVersion\":3")&&!File.ReadAllText(path).Contains("motor-start-v1"),"intentional motor removal restores source-only format with no stale capability");Check(File.ReadAllText(path+".bak").Contains("\"FileVersion\":4")&&Project.Load(path).Boards[0].Circuits[0].PowerKw==c.PowerKw,"format change preserves prior motor project backup and electrical input");
  var clone=ProjectEditing.DuplicateCircuit(p,b,c);Check(clone.MotorStarting!=c.MotorStarting&&clone.MotorStarting.StartingCurrentA==90,"duplicate owns independent motor data");MotorStarting.Remove(clone);Check(clone.MotorStarting==null&&clone.PowerKw==c.PowerKw,"removing model preserves electrical input");b.Circuits.Remove(clone);
  using(var form=new MotorStartingForm(p,b,c)){form.CreateControl();var values=Field<Dictionary<string,TextBox>>(form,"numbers");values["Shaft"].Text="9";values["Efficiency"].Text="0,9";form.GetType().GetMethod("ApplyValues",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(form,null);Check(form.Changed&&c.PowerKw==10,"editor parses decimal comma and applies consistent motor");if(Environment.GetEnvironmentVariable("CIRCUITO_QA_VISUAL")=="1"){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(10,10);form.Show();Application.DoEvents();string artifacts=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"referencias-motor");Directory.CreateDirectory(artifacts);using(var bitmap=new Bitmap(form.ClientSize.Width,form.ClientSize.Height)){using(var g=Graphics.FromImage(bitmap))g.CopyFromScreen(form.PointToScreen(Point.Empty),Point.Empty,form.ClientSize);bitmap.Save(Path.Combine(artifacts,"motor.png"));}form.Hide();}}
  Console.WriteLine("PASS: "+n+" motor starting assertions including electrical input, analytical drop, pending models, persistence and capabilities");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{Directory.Delete(dir,true);}}
}
